using System;
using System.Collections.Generic;
using System.Linq;
using System.Threading;
using System.Threading.Tasks;
namespace SplifyWin {
 public static class AdaptiveStrategySearch {
  public static List<CustomStrategyDefinition> Initial(ZapretStrategy[] catalog,string name,int limit,string preferred){return CustomStrategies.Generate(catalog,name,24,preferred).Take(limit==12?6:8).ToList();}
  static string Signature(CustomStrategyDefinition definition,ZapretStrategy[] catalog){var built=CustomStrategies.Build(definition,catalog);return built.Tcp+"\n"+built.Udp;}
  static IEnumerable<IGrouping<string,ZapretCheckRow>> Trials(ZapretCheckReport report){return report.Rows.Where(r=>!r.Checking&&!String.IsNullOrEmpty(r.StrategyId)).GroupBy(r=>r.StrategyId);}
  static int Coverage(IEnumerable<ZapretCheckRow> trials,string[] services){return trials.Min(r=>String.IsNullOrEmpty(r.Error)?services.Count(s=>r.Access(s)==ServiceAccess.Available):0);}
  static long Latency(IEnumerable<ZapretCheckRow> trials,string[] services){return trials.Max(r=>services.Sum(s=>{var result=r.Services.FirstOrDefault(v=>v.Id==s);return result==null||result.Access!=ServiceAccess.Available||result.Milliseconds<=0?1000000L:result.Milliseconds;}));}
  public static string[] Rank(ZapretCheckReport report,string[] services){return Trials(report).OrderByDescending(g=>Coverage(g,services)).ThenByDescending(g=>g.Min(r=>r.Services.Where(v=>services.Contains(v.Id)&&v.Access==ServiceAccess.Available).Sum(v=>v.SuccessfulRequests))).ThenBy(g=>Latency(g,services)).ThenBy(g=>g.Key,StringComparer.Ordinal).Select(g=>g.Key).ToArray();}
  public static ZapretCheckRow BestForService(ZapretCheckReport report,string service,bool confirmed){var best=Trials(report).Where(g=>(!confirmed||g.Count()>=3)&&Coverage(g,new[]{service})==1).OrderBy(g=>Latency(g,new[]{service})).ThenBy(g=>g.Key,StringComparer.Ordinal).FirstOrDefault();return best==null?null:best.Last();}
  static List<CustomStrategyDefinition> Neighbours(CustomStrategyDefinition winner,ZapretStrategy[] catalog,string prefix){
   var built=CustomStrategies.Build(winner,catalog);var axes=new List<Tuple<bool,string,string[]>>{Tuple.Create(true,"repeats",new[]{"1","2","4","6"}),Tuple.Create(true,"cutoff",new[]{"n1","n2","n4","n8"})};
   if(built.Tcp.Contains("--dpi-desync-split-pos="))axes.Add(Tuple.Create(true,"split-pos",new[]{"2","1,midsld"}));if(built.Tcp.Contains("--dpi-desync-ttl="))axes.Add(Tuple.Create(true,"ttl",new[]{"2","3","4","5"}));if(!String.IsNullOrWhiteSpace(built.Udp)){axes.Add(Tuple.Create(false,"repeats",new[]{"1","2","4","6"}));axes.Add(Tuple.Create(false,"cutoff",new[]{"n1","n2","n4","n8"}));}
   var result=new List<CustomStrategyDefinition>();for(int level=0;level<4;level++)foreach(var axis in axes){if(level>=axis.Item3.Length)continue;var draft=new CustomStrategyDefinition{Id="local:"+Guid.NewGuid().ToString("N"),Name=prefix,BaseId=winner.BaseId,Generated=true,TcpOverrides=winner.TcpOverrides==null?new Dictionary<string,string>():new Dictionary<string,string>(winner.TcpOverrides),UdpOverrides=winner.UdpOverrides==null?new Dictionary<string,string>():new Dictionary<string,string>(winner.UdpOverrides)};(axis.Item1?draft.TcpOverrides:draft.UdpOverrides)[axis.Item2]=axis.Item3[level];result.Add(draft);}return result;
  }
  public static async Task Run(ZapretCheckReport report,List<CustomStrategyDefinition> definitions,ZapretStrategy[] catalog,string name,int limit,CancellationToken cancellation,Func<ZapretCheckReport,ZapretStrategy[],CancellationToken,Action<string>,Action<ZapretCheckReport>,Task> scan,Action<string> say,Action<ZapretCheckReport> save){
   if(limit!=12&&limit!=24)throw new ArgumentException("Размер поиска: 12 или 24");report.Adaptive=true;report.Complete=false;report.StartedAt=DateTime.Now;var started=report.StartedAt;string[] services=report.Settings.CheckServices.ToArray();var seen=new HashSet<string>(definitions.Select(d=>Signature(d,catalog)));int confirmation=limit==12?2:4,used=0;bool completed=false;
   Func<CustomStrategyDefinition[],string,Task> measure=async(batch,stage)=>{cancellation.ThrowIfCancellationRequested();say(stage+" · "+batch.Length+" проверок");used+=batch.Length;await scan(report,batch.Select(d=>CustomStrategies.Build(d,catalog)).ToArray(),cancellation,say,value=>{value.Adaptive=true;value.StartedAt=started;value.Planned=limit;value.Complete=false;save(value);});report.Complete=false;};
   try{
    await measure(definitions.ToArray(),"Шаг 1: измеряем разные основы на текущем подключении");
    while(used<limit-confirmation){cancellation.ThrowIfCancellationRequested();var ranked=Rank(report,services);var promising=ranked.Where(id=>report.Rows.Any(r=>r.StrategyId==id&&String.IsNullOrEmpty(r.Error)&&services.Any(s=>r.Access(s)==ServiceAccess.Available))).ToList();foreach(var service in services){var winner=BestForService(report,service,false);if(winner!=null&&!promising.Take(2).Contains(winner.StrategyId))promising.Insert(Math.Min(1,promising.Count),winner.StrategyId);}if(promising.Count==0){say("Ни одна основа не подтвердила выбранные сервисы. Не продолжаем слепой перебор; проверьте доступность сети и сервисов.");break;}
     var candidates=new List<CustomStrategyDefinition>();var sources=promising.Distinct().Take(2).Select(id=>definitions.First(d=>d.Id==id)).ToArray();var queues=sources.Select(d=>new Queue<CustomStrategyDefinition>(Neighbours(d,catalog,name))).ToArray();int batchSize=Math.Min(3,limit-confirmation-used);while(candidates.Count<batchSize&&queues.Any(q=>q.Count>0))foreach(var queue in queues){if(queue.Count==0)continue;var draft=queue.Dequeue();if(seen.Add(Signature(draft,catalog))){draft.Name=name.Trim()+" · "+(definitions.Count+candidates.Count+1).ToString("00");candidates.Add(draft);}if(candidates.Count==batchSize)break;}if(candidates.Count==0)break;definitions.AddRange(candidates);await measure(candidates.ToArray(),"Шаг 2: меняем один параметр у лучших измеренных вариантов");
    }
    var finalists=new List<string>();foreach(var service in services){var best=BestForService(report,service,false);if(best!=null&&!finalists.Contains(best.StrategyId))finalists.Add(best.StrategyId);}foreach(var id in Rank(report,services))if(!finalists.Contains(id))finalists.Add(id);finalists=finalists.Where(id=>report.Rows.Any(r=>r.StrategyId==id&&String.IsNullOrEmpty(r.Error)&&services.Any(s=>r.Access(s)==ServiceAccess.Available))).Take(confirmation/2).ToList();
    for(int repeat=0;repeat<2;repeat++)if(finalists.Count>0)await measure(finalists.Select(id=>definitions.First(d=>d.Id==id)).ToArray(),"Шаг 3: повторно подтверждаем победителей, проверка "+(repeat+1)+" / 2");
    foreach(var service in services){var best=BestForService(report,service,true);say(best==null?service+": стабильный вариант не подтверждён":service+": рекомендуем "+best.Name+" — доступность подтверждена минимум трижды");}completed=true;
   }catch(OperationCanceledException){report.StopReason="Адаптивный поиск остановлен. Завершённые проверки сохранены.";throw;}
   finally{report.StartedAt=started;report.Planned=used;report.Complete=completed;report.FinishedAt=DateTime.Now;save(report);}
  }
 }
}
